Ext._define('standard.configuration.item.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'standard.configuration.item.Window',


    statics: {
        types: [],
        menu_structure: [],
        filter_structure: [],

        register: function (name,Class) {
            standard.configuration.item.Grid.types.push({
                name: name,
                Class: Class
            });
        },

        getClassByName: function (name) {
            var Class = false;
            standard.configuration.item.Grid.types.forEach(
                function (item) {
                    if (item.name == name) {
                        Class = item.Class;
                        return false;
                    }
                }
            );
            return Class;
        },
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Aplicativo', dataIndex: 'configuration_unicode',id: 'autoExpandColumn'},
                    {header: 'Chave', dataIndex: 'key',  width: 250},
                    {header: 'Nome', dataIndex: 'name',width: 300},
                    {header: 'Valor', dataIndex: 'value', width: 200},
                ]
            );

        return this._columnModel;
    },


    createItem: function () {
        var _class = standard.configuration.item.Grid.getClassByName(this.getParams().application);
        if(!_class)
            _class = 'standard.configuration.item.Window';
        this.restWindow = _class;
        standard.configuration.item.Grid.superclass.createItem.call(this);
    },

    updateItem: function (record) { 
        var selected = this.getSelectionModel().getSelected();
        if (selected) {
            var _class = standard.configuration.item.Grid.getClassByName(selected.get('type'));
            if(!_class)
                _class = 'standard.configuration.item.Window';
            this.restWindow = _class;
        }
        standard.configuration.item.Grid.superclass.updateItem.call(this, record);
    },

});

