/*
 * src: /app/root/static/js/toolkit/questionario/MontaQuestionario.js
 */
Ext.ns('toolkit.questionario');

toolkit.questionario.MontaQuestionario = Ext.extend(

    Ext.Window,
    {
        retorno:null,

        constructor: function(cfg, questoes, titulo_questionario){
            this.questoes = questoes;
            this.titulo_questionario = titulo_questionario;
            if(this.titulo_questionario==undefined)
                this.titulo_questionario='';
            cfg = (cfg ? cfg : {});
            Ext.apply(cfg, {
                'layout':'fit',
                'width': 600,
                'height': 570,
                'closable':true,
                'autoScroll': true,
                'items':this.getFormPanel(),
                'buttons': [
                {
                    'text': 'Salvar',
                    'scope': this,
                    'handler': this.save
                },
                {
                    'text': 'Cancelar',
                    'scope': this,
                    'handler': this.destroy
                }
                ]   
            });

            toolkit.questionario.MontaQuestionario.superclass.constructor.call(this, cfg);
        },

        createQuestionario: function(){
            var items = [];
            items[items.length] = {
                'xtype':'displayfield',
                'hideLabel':true,
                'value': '<b><font size="4">'+this.titulo_questionario + '</font></b><br><br>'
            };

            Ext.each(this.questoes, function(questao){
                var chave = questao.chave
                var el = {};
                if (questao.tipo == 'Questão Aberta')
                {
                    el = {
                        'xtype':'ckeditor',
                        'hideLabel':true,
                        'height':100,
                        // 'disabled':true,
                        'autoWidth':true,
                        'name': questao.label+':'+chave+':'+questao.id_questionario+':'+questao.id
                    };
                }
                else if(questao.tipo == 'Questão Enum')
                {
                    var alts = [];
                    Ext.each(this.alternativas, function(alt){
                   
                        alts[alts.length]= {
                            'xtype':'textfield',
                            'fieldLabel':alt.label+ ' '+alt.texto,
                            'width':30,
                            'maxLength': 4,
                            'labelAlign':'left',
                            'maxLengthText':'Insira no máximo quatro digitos',
                            'name': questao.label+':'+chave+':'+questao.id_questionario+':'+questao.id+':'+alt.id
                        }
                    });
                   
                    el = alts;
                }
                else if(questao.tipo == 'Questão MS')
                {
                    var alts = [];
                    Ext.each(this.alternativas, function(alt){
                        alts[alts.length] = {
                            'boxLabel': alt.label+ ' '+alt.texto, 
                            'allowBlank':false,
                            'name': questao.label+':'+chave+':'+questao.id_questionario+':'+questao.id,
                            'inputValue':alt.id 
                        };
                    });
                    if(questao.mista==true)
                    {
                        alts[alts.length] = {
                            'xtype': 'ckeditor',
                            'hideLabel':true,
                            'height':100,
                            'autoWidth':true,
                            'name': questao.label+':'+chave+':'+questao.id_questionario+':'+questao.id
                        };
                    }
                    if(alts.length>0)
                    {
                        el = {
                            'xtype':'checkboxgroup',
                            'hideLabel':true,
                            'columns': 1,
                            'items': alts
                        }
                    }
                }
                else if (questao.tipo == 'Questão')
                {
                    var alts = [];
                    Ext.each(this.alternativas, function(alt){
                        alts[alts.length] = {
                            // 'disabled':true,
                            'boxLabel': alt.label+ ' '+alt.texto, 
                            'name': questao.label+':'+chave+':'+questao.id_questionario+':'+questao.id,
                            'inputValue':alt.id
                        };
                    });
                    if(questao.mista==true)
                    {
                        alts[alts.length] = {
                            'xtype': 'ckeditor',
                            'hideLabel':true,
                            'height':100,
                            'autoWidth':true,
                            'name': questao.label+':'+chave+':'+questao.id_questionario+':'+questao.id
                        };
                    }
                    if(alts.length>0)
                    {
                        el = {
                            'xtype':'radiogroup',
                            'hideLabel':true,
                            'columns': 1,
                            'items': alts,
                            'allowBlank': false
                        }
                    }
                }

                if(questao.tipo == 'Ref. Textual')
                {    
                    items[items.length] = {
                        'xtype':'displayfield',
                        'labelAlign': 'top',
                        'hideLabel':true,
                        'value':'<b>'+this.label_ele+ ' - '+ this.label+'<br><i>'+this.conteudo+'</i></b><br>',
                    };
                }else {
                    items[items.length] = {
                        'xtype':'fieldset',
                        'hideLabel':true,
                        'title': questao.label+' - '+questao.enunciado,
                        'items':[el]
                    };
                }
            })
            return items;
        },

        getFormPanel: function() {
            if(!this._formPanel)
                this._formPanel = new Ext.form.FormPanel({
                    'frame': true,
                    'hideLabel':true,
                    'autoWidth':true,
                    'autoScroll':true,
                    'items': this.createQuestionario()
                });
        
            return this._formPanel;
        },

        getParams: function() {
            return this.params;
        },

        save: function() {

            Ext.Msg.show({
                'title': 'Atenção',
                'msg': 'Tem certeza que deseja finalizar? Verifique se preencheu corretamente o questionário antes de concluir. ',
                'icon': Ext.Msg.QUESTION,
                'buttons': Ext.Msg.YESNO,
                'scope': this,
                'fn': function(b) {
                    if(b == 'no') return;

                    var form = this.getFormPanel().getForm();
                    form.waitMsgTarget = this.getEl();
                    form.submit({
                        'url': toolkit.util.Normalize.controller_action('QMontarQuestionario', this.action),
                        'params': this.getParams(),
                        'scope': this,
                        'success': function(form, action) {
                            // console.log(action.result.data);
                            this.retorno = action.result.data;
                            // Ext.Msg.alert('Sucesso', 'Dados salvos com sucesso!');
                            if(this.callback && this.callback.success)
                                this.callback.success.handler.call(this.callback.success.scope ? this.callback.success.scope : window);
                            this.destroy()
                        },
                        'failure': function(form, action) {
                            var message = ''
                            if(action.failureType == 'connect')
                                message = 'Não consegui acessar o recurso no servidor.'
                            else
                                message = action.result.message
                            Ext.Msg.show({
                                'title': 'Questionário',
                                'msg': message,
                                'icon': Ext.Msg.ERROR,
                                'buttons': Ext.Msg.OK
                            });

                            if(this.callback && this.callback.failure)
                                this.callback.failure.handler.call(this.callback.failure.scope ? this.callback.failure.scope : window);
                        },
                        'waitMsg': 'Salvando dados...'
                    })
                }
            });


        }
      
    }
    );
/*
 * src: /app/root/static/js/toolkit/questionario/VerResposta.js
 */
Ext.ns('toolkit.questionario');

toolkit.questionario.VerResposta = Ext.extend(
    Ext.Window,
    {
       
        // constructor: function(cfg, questionario, param, url) {
        constructor: function(cfg, param, url) {
            this.param = param
            this.url = url

            cfg = (cfg ? cfg : {});
            Ext.apply(cfg, {
                // 'title': 'Lista de Respostas',
                'closable': true,
                'autoScroll': true,
                'modal': true,
                'width': 430,
                'height': 330,
                'border': false,
                'items':this.getGrid()
            });

            toolkit.questionario.VerResposta.superclass.constructor.call(this, cfg);
        },

        getStore: function() {
            if(!this._store){
                this._store = new Ext.data.Store({
                    proxy: new Ext.data.HttpProxy({
                        'url': toolkit.util.Normalize.controller_action('QMontarQuestionario', 'ver_resposta'),
                        'method': 'GET',
                        'disableCaching': false
                    }),
                    reader: new Ext.data.JsonReader({
                        'totalProperty': 'count',
                        'root': 'collection',
                        'fields': [
                        'data',
                        'enunciado',
                        'tipo',
                        'alternativas',
                        'respostas',
                        'mista',
                        ]
                    }),
                    scope:this
                });
            }
            return this._store;
        },

        getTpl: function(){
            return new xDataView({
                store: this.getStore(),
                autoHeight:true,
                multiSelect: true,
                overClass:'list-hover',
                itemSelector:'.list-item',
                emptyText: 'Sem itens para exibir.',
                tpl: new xTemplate(
                    '<tpl for="." >',
                        '<div class="list">',
                            '<b><p>{enunciado} </p></b>',
                            '<tpl if="tipo != \'Ref. Textual\'">', 
                                '<div class="list_alt">',
                            '</tpl>',
                            '<tpl for="alternativas">',
                                '<ul><li>',
                                '<tpl if="flag == 0">',
                                '<p>',
                                '</tpl>',
                                '{label} {texto}',
                                '</li></ul>',
                            '</tpl>',
                            '</div>',
                            '<tpl if="tipo != \'Ref. Textual\'">', 
                                '<div class="list_resp">',
                            '</tpl>',
                            '<tpl if="tipo != \'Ref. Textual\'">', 
                                '<i><h6>Respondido em: {data}:</h6></i><br>',
                            '</tpl>',
                            '<tpl if="tipo != \'Questão\'">', 
                                '<tpl for="respostas">',
                                    '<i>{label} {alternativa} </i>',
                                    '<i>{texto}<br></i> ',
                                '</tpl>',
                            '</tpl>',
                            '</div>',
                        '</div>',
                    '</tpl>'
                    )
            });
        },

        getStoreGrid: function() {
            if(!this._gStore){
                this._gStore = new Ext.data.JsonStore({
                    autoLoad:true,
                    root: 'collection',
                    totalProperty: 'count',
                    fields: [
                    'pk', 
                    'data', 
                    'titulo'
                    ],
                    url: this.url,
                    // url: toolkit.util.Normalize.controller_action('QMontarQuestionario','get_resp',[this.questionario,this.param]),
                    // url: toolkit.util.Normalize.controller_action('QMontarQuestionario','get_data_resposta'),
                    // baseParams:{pk_questionario: this.questionario, pk_param: this.param},
                    scope:this
                });
            }
            return this._gStore;
        },

        getGrid: function(){
            if(!this._grid){
                this._grid = new Ext.grid.GridPanel({
                    'scope':this,
                    'width':415,
                    'height': 280,
                    'store': this.getStoreGrid(),
                    'bbar': this.getPagingToolbar(),
                    'columns':[
                    {
                        dataIndex:'titulo', 
                        header:'Titulo do Questionário', 
                        width:260
                    },
                    {
                        dataIndex:'data', 
                        header:'Data', 
                        width:80
                    },
                    {
                        xtype: 'actioncolumn',
                        header:'Visualizar',
                        width: 65,
                        scope:this,
                        items:
                        [
                        {
                            tooltip:'Visualizar Resposta',  
                            icon: '/' + global.Context + '/static/images/document-validate.png',
                            handler: function(grid, row, col)
                            {
                                var record = grid.getStore().getAt(row);
                                var verResposta = new Ext.Window({
                                    'title':record.get('titulo')+' - '+record.get('data'),
                                    'width':500,
                                    'height':500,
                                    'modal': true,
                                    'autoScroll':true,
                                    'items':this.getTpl(),
                                    'listeners': {
                                        show:function(){
                                            this.getStore().load({
                                                params:{
                                                    pk_questionario_resposta:record.get('pk'), 
                                                    pk_param: this.param
                                                }
                                            });
                                        },
                                        scope:this
                                    }
                                });
                                verResposta.show()
                            },
                            scope:this
                        }
                        ]
                    }
                    ],
                    'listeners': {
                        'scope': this,
                        'render': function(grid) {
                            new Ext.LoadMask(grid.getEl(), {
                                'store': grid.getStore(),
                                'msg': 'Carregando Respostas...'
                            });
                        }
                    }
                });

            }
            return this._grid;
        },

        getPagingToolbar: function() {
            if(!this._pagingToolbar){
                this._pagingToolbar = new Ext.PagingToolbar({
                    'style': 'border-left:none',
                    'store': this.getStoreGrid(),
                    'pageSize':15,
                    'displayInfo': true
                });
            }        
            return this._pagingToolbar;
        }
    }
    );
/*
 * src: /app/root/static/js/toolkit/questionario/core.js
 */
Ext.ns('toolkit.questionario');

Ext.apply(toolkit.questionario, {

    rendererIconGrid: function(value) {
        var tpl = new Ext.XTemplate('<div class="tk-grid-icon-cell {iconCls}" ext:qtip="{title}" <tpl if="width">ext:qwidth="{width}</tpl>"></div>');
        var out = '';

        Ext.each(value, function(item) {
            if(item)
                out += tpl.apply({
                    'iconCls': item.iconCls,
                    'title': item.title,
                    'width': (item.width ? item.width : false)
                });
        });

        return out;
    }

});
